class Solution:

	def find(self, board, word):
		visited = [[False for i in range(len(board[0]))] for j in range(len(board))]

		def dfs(r, c, pos):
			if pos == len(word):
				return True
			if 0 <= r < len(board) and 0 <= c < len(board[0]) and (visited[r][c] == False) and (board[r][c] == word[pos]):
				visited[r][c] = True
				if dfs(r + 1, c, pos + 1) or dfs(r, c + 1, pos + 1) or dfs(r - 1, c, pos + 1) or dfs(r, c - 1, pos + 1) or dfs(r + 1, c + 1, pos + 1) or dfs(r + 1, c - 1, pos + 1) or dfs(r - 1, c + 1, pos + 1) or dfs(r - 1, c - 1, pos + 1):
					return True
				visited[r][c] = False
			return False
		indx = 0
		for i in range(len(board)):
			for j in range(len(board[0])):
				if board[i][j] == word[indx]:
					if dfs(i, j, indx):
						return True
		return False

	def wordBoggle(self, board, dictionary):
		res = []
		for i in range(len(dictionary)):
			word = dictionary[i]
			if self.find(board, word):
				res.append(word)
		return list(set(res))
